const express = require('express');
const app = express();

let pgPool;

function getPgPool() {
  if (!pgPool) {
    // Load pg lazily so the rest of the API can still start even if the
    // database client is unavailable; /healthz will report that as unhealthy.
    // eslint-disable-next-line global-require
    const { Pool } = require('pg');

    pgPool = new Pool({
      connectionString: process.env.DATABASE_URL,
      host: process.env.PGHOST,
      port: process.env.PGPORT ? Number(process.env.PGPORT) : undefined,
      database: process.env.PGDATABASE,
      user: process.env.PGUSER,
      password: process.env.PGPASSWORD,
      connectionTimeoutMillis: Number(process.env.HEALTHZ_DB_TIMEOUT_MS || 1000),
    });
  }

  return pgPool;
}

async function checkDb() {
  const pool = getPgPool();
  await pool.query('SELECT 1');
}

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/healthz', async (req, res) => {
  try {
    await checkDb();
    res.status(200).json({ db: 'ok' });
  } catch (err) {
    res.status(503).json({ db: 'error' });
  }
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

if (require.main === module) {
  app.listen(3000, () => {
    console.log('Server running on port 3000');
  });
}

module.exports = app;

