const DB_HEALTHCHECK_TIMEOUT_MS = Number(process.env.DB_HEALTHCHECK_TIMEOUT_MS || 1000);

function getPostgresClientConfig() {
  const config = {
    connectionTimeoutMillis: DB_HEALTHCHECK_TIMEOUT_MS,
  };

  if (process.env.DATABASE_URL) {
    config.connectionString = process.env.DATABASE_URL;
  }

  return config;
}

async function checkPostgres() {
  // Load pg lazily so the application can still be imported in tests that do
  // not exercise database-backed routes.
  // eslint-disable-next-line global-require
  const { Client } = require('pg');
  const client = new Client(getPostgresClientConfig());

  try {
    await client.connect();
    await client.query('SELECT 1');
  } finally {
    await client.end().catch(() => {});
  }
}

